from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces in the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify the start and end indices of each group of nested parentheses
    groups = []
    start = 0
    stack = []

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            start = stack.pop()
            groups.append(paren_string[start:i+1])

    # Step 3: Extract each group of nested parentheses using the indices
    result = [group for group in groups]

    # Step 4: Check if each group is balanced and properly closed
    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    result = [group for group in result if is_balanced(group)]

    # Step 5: Return the list of separated groups
    return result

